/*!
 * LG ThinQ Washer Card — custom Lovelace card for Home Assistant
 * Works with the official `lg_thinq` integration (washer / washtower / washcombo).
 * MIT License
 */

const CARD_VERSION = "1.2.0";

/* Zdjęcia bębna (wbudowane, JPEG base64) */
const DRUM_PHOTO_ACTIVE = "data:image/jpeg;base64,";
const DRUM_PHOTO_IDLE = "data:image/jpeg;base64,";


/* ------------------------------------------------------------------ */
/*  Słowniki                                                           */
/* ------------------------------------------------------------------ */

const STATUS_PL = {
  running: "W trakcie prania",
  rinsing: "Płukanie",
  spinning: "Wirowanie",
  drying: "Suszenie",
  refreshing: "Odświeżanie",
  detecting: "Wykrywanie wsadu",
  steam_softening: "Zmiękczanie parą",
  rinse_hold: "Wstrzymane płukanie",
  cool_down: "Schładzanie",
  pause: "Pauza",
  reserved: "Zaplanowane",
  sleep: "Uśpiona",
  end: "Pranie zakończone",
  error: "Błąd",
  initial: "Gotowa do pracy",
  power_off: "Gotowa do pracy",
  unknown: "Gotowa do pracy",
  unavailable: "Niedostępna",
};

const ERROR_PL = {
  unable_to_lock_error: "Nie można zablokować drzwi",
  locked_motor_error: "Zablokowany silnik",
  overfill_error: "Przepełnienie wodą",
  door_open_error: "Otwarte drzwi",
  water_drain_error: "Problem z odpływem wody",
  water_level_sensor_error: "Błąd czujnika poziomu wody",
  temperature_sensor_error: "Błąd czujnika temperatury",
  out_of_balance_error: "Niewyważony wsad",
  power_fail_error: "Zanik zasilania",
  water_supply_error: "Brak dopływu wody",
};

// stany, w których bęben "pracuje"
const ACTIVE = [
  "running", "rinsing", "spinning", "drying", "refreshing", "detecting",
  "steam_softening", "rinse_hold", "cool_down",
];
// stany, w których jest aktywny cykl (także pauza / zaplanowane)
const IN_CYCLE = [...ACTIVE, "pause", "reserved"];

// etap na wyświetlaczu: 0 Pranie, 1 Płukanie, 2 Wirowanie, 3 Koniec
const STAGE_OF = {
  detecting: 0, running: 0, steam_softening: 0, refreshing: 0,
  rinsing: 1, rinse_hold: 1,
  spinning: 2, drying: 2, cool_down: 2,
  end: 3,
};
const STAGES = ["Pranie", "Płukanie", "Wirowanie", "Koniec"];
const STAGE_ICONS = ["mdi:washing-machine", "mdi:water-outline", "mdi:rotate-right", "mdi:check-circle-outline"];

const DEFAULT_PROGRAMS = [
  "Bawełna", "Eco 40-60", "TurboWash 39", "Mieszane", "Syntetyczne", "Delikatne", "Antyalergiczny",
  "Szybki 14", "Sportowe", "Wełna", "Pościel", "Czyszczenie bębna", "Płukanie + Wirowanie", "Mój program",
];

// klucz -> [domena, sufiks]  (domyślnie: <domena>.<prefix>_<sufiks>)
const ENTITY_DEFAULTS = {
  power: ["switch", "power"],
  operation: ["select", "operation"],
  status: ["sensor", "current_status"],
  remaining_time: ["sensor", "remaining_time"],
  total_time: ["sensor", "total_time"],
  delayed_end: ["number", "delayed_end"],
  delayed_end_time: ["sensor", "delayed_end"],
  remote_start: ["binary_sensor", "remote_start"],
  cycles: ["sensor", "cycles"],
  energy_today: ["sensor", "energy_today"],
  energy_yesterday: ["sensor", "energy_yesterday"],
  energy_this_month: ["sensor", "energy_this_month"],
  energy_last_month: ["sensor", "energy_last_month"],
  error: ["event", "error"],
  notification: ["event", "notification"],
  // opcjonalne — LG ThinQ ich standardowo nie wystawia dla pralek
  program: null,
  temperature: null,
  spin: null,
};

/* ------------------------------------------------------------------ */
/*  Pomocnicze                                                         */
/* ------------------------------------------------------------------ */

const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const BAD = ["unknown", "unavailable", "none", "", null, undefined];
const ok = (st) => st && !BAD.includes(st.state);

const fmtHM = (min) => {
  if (min == null || isNaN(min) || min < 0) return null;
  const m = Math.round(min);
  return `${Math.floor(m / 60)}:${String(m % 60).padStart(2, "0")}`;
};

const fmtEnergy = (st) => {
  if (!ok(st)) return "–";
  let v = parseFloat(st.state);
  if (isNaN(v)) return esc(st.state);
  const unit = (st.attributes.unit_of_measurement || "Wh").toLowerCase();
  if (unit === "kwh") v *= 1000;
  if (Math.abs(v) < 1000) return `${Math.round(v).toLocaleString("pl-PL")} Wh`;
  return `${(v / 1000).toLocaleString("pl-PL", { minimumFractionDigits: 3, maximumFractionDigits: 3 })} kWh`;
};

const normalize = (s) =>
  String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/ł/g, "l").replace(/[^a-z0-9]/g, "");

/* ------------------------------------------------------------------ */
/*  Grafika bębna (SVG)                                                */
/* ------------------------------------------------------------------ */

function drumSvg(mode /* idle | active | paused */) {
  const holes = [];
  for (let r = 40; r <= 104; r += 13) {
    const n = Math.round((2 * Math.PI * r) / 13);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + r;
      holes.push(`<circle cx="${(160 + r * Math.cos(a)).toFixed(1)}" cy="${(160 + r * Math.sin(a)).toFixed(1)}" r="1.6"/>`);
    }
  }
  const lifters = [0, 120, 240]
    .map(
      (deg) => `<g transform="rotate(${deg} 160 160)">
        <path d="M148 62 Q160 52 172 62 L176 128 Q160 140 144 128 Z" fill="url(#lgw-lifter)" stroke="#1a1d21" stroke-width="1"/>
        <path d="M152 66 L156 124" stroke="rgba(255,255,255,.35)" stroke-width="2" stroke-linecap="round"/>
      </g>`
    )
    .join("");

  const empty = `
    <circle cx="160" cy="160" r="112" fill="url(#lgw-drum)"/>
    <g fill="#05070a" opacity=".85">${holes.join("")}</g>
    ${lifters}
    <circle cx="160" cy="160" r="22" fill="url(#lgw-hub)" stroke="#2a2f35" stroke-width="2"/>
    <circle cx="160" cy="160" r="7" fill="#0a0c0f"/>`;

  const clothes = `
    <circle cx="160" cy="160" r="112" fill="url(#lgw-drum)"/>
    <g fill="#05070a" opacity=".6">${holes.join("")}</g>
    <g class="lgw-water">
      <path d="M30 175 Q70 160 110 172 T190 170 T290 168 L290 290 L30 290 Z" fill="url(#lgw-water)" opacity=".85"/>
    </g>
    <g class="lgw-clothes ${mode === "active" ? "spin" : ""}">
      <path d="M95 150 Q120 105 175 118 Q215 128 228 168 Q210 212 160 214 Q110 210 95 150Z" fill="#2c64c8"/>
      <path d="M110 160 Q130 125 170 135 Q200 145 205 175 Q190 200 160 200 Q125 196 110 160Z" fill="#4c8ef0"/>
      <path d="M78 190 Q100 165 140 182 Q170 196 150 232 Q118 248 92 230 Q74 214 78 190Z" fill="#1d4fa8"/>
      <path d="M180 190 Q215 178 238 200 Q246 230 214 240 Q186 242 176 222Z" fill="#86b6ff"/>
      <path d="M120 120 Q150 100 190 110 Q170 130 140 134 Q122 134 120 120Z" fill="#c9dcff" opacity=".9"/>
      <path d="M128 172 Q150 160 176 168" stroke="#9cc2ff" stroke-width="4" fill="none" stroke-linecap="round" opacity=".7"/>
      <path d="M96 204 Q118 196 136 206" stroke="#6ea2ff" stroke-width="3" fill="none" stroke-linecap="round" opacity=".7"/>
    </g>
    <g class="lgw-bubbles" fill="#ffffff">
      <circle cx="120" cy="230" r="4" opacity=".35"/><circle cx="208" cy="214" r="3" opacity=".4"/>
      <circle cx="240" cy="180" r="5" opacity=".25"/><circle cx="90" cy="176" r="3" opacity=".35"/>
      <circle cx="180" cy="246" r="2.5" opacity=".5"/><circle cx="150" cy="110" r="2" opacity=".5"/>
    </g>`;

  return `
  <svg viewBox="0 0 320 320" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
    <defs>
      <linearGradient id="lgw-bezel" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="#e6e9ec"/><stop offset=".25" stop-color="#8d949b"/>
        <stop offset=".5" stop-color="#2b3036"/><stop offset=".75" stop-color="#9aa1a8"/>
        <stop offset="1" stop-color="#3a3f45"/>
      </linearGradient>
      <linearGradient id="lgw-ring" x1="1" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#555b62"/><stop offset=".5" stop-color="#15181c"/><stop offset="1" stop-color="#7c838a"/>
      </linearGradient>
      <radialGradient id="lgw-drum" cx=".45" cy=".4" r=".7">
        <stop offset="0" stop-color="#8b9299"/><stop offset=".55" stop-color="#4a5057"/><stop offset="1" stop-color="#16191d"/>
      </radialGradient>
      <linearGradient id="lgw-lifter" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stop-color="#5b6168"/><stop offset=".5" stop-color="#c8ced4"/><stop offset="1" stop-color="#4a5057"/>
      </linearGradient>
      <radialGradient id="lgw-hub" cx=".4" cy=".35" r=".7">
        <stop offset="0" stop-color="#d9dee3"/><stop offset="1" stop-color="#3a3f45"/>
      </radialGradient>
      <linearGradient id="lgw-water" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#7cc0ff" stop-opacity=".75"/><stop offset="1" stop-color="#0b3b84"/>
      </linearGradient>
      <radialGradient id="lgw-glass" cx=".35" cy=".3" r=".8">
        <stop offset="0" stop-color="#ffffff" stop-opacity=".14"/><stop offset=".5" stop-color="#ffffff" stop-opacity=".03"/>
        <stop offset="1" stop-color="#000000" stop-opacity=".35"/>
      </radialGradient>
      <clipPath id="lgw-clip"><circle cx="160" cy="160" r="112"/></clipPath>
    </defs>
    <rect width="320" height="320" fill="#0c1015"/>
    <circle cx="160" cy="160" r="156" fill="url(#lgw-bezel)"/>
    <circle cx="160" cy="160" r="146" fill="#0d1014"/>
    <circle cx="160" cy="160" r="132" fill="url(#lgw-ring)"/>
    <circle cx="160" cy="160" r="120" fill="#0a0c0f"/>
    <g clip-path="url(#lgw-clip)">
      ${mode === "idle" ? empty : clothes}
      <circle cx="160" cy="160" r="112" fill="url(#lgw-glass)"/>
      <path d="M78 110 A95 95 0 0 1 150 62" stroke="#fff" stroke-opacity=".28" stroke-width="6" fill="none" stroke-linecap="round"/>
    </g>
    <circle cx="160" cy="160" r="112" fill="none" stroke="#2c3238" stroke-width="3"/>
  </svg>`;
}

/* ------------------------------------------------------------------ */
/*  Karta                                                              */
/* ------------------------------------------------------------------ */

class LgThinqWasherCard extends HTMLElement {
  static getStubConfig(hass) {
    let prefix = "frania";
    if (hass) {
      const found = Object.keys(hass.states).find((e) => /^select\..+_operation$/.test(e) && hass.states[e].attributes.options?.includes("wake_up"));
      if (found) prefix = found.replace(/^select\./, "").replace(/_operation$/, "");
    }
    return { prefix, name: "Pralka" };
  }

  static getConfigElement() {
    return document.createElement("lg-thinq-washer-panel-card-editor");
  }

  setConfig(config) {
    if (!config || (!config.prefix && !config.entities)) {
      throw new Error("Podaj `prefix` (np. frania) albo sekcję `entities`.");
    }
    this._config = {
      name: "Pralka",
      subtitle: "LG ThinQ",
      brand: "LG",
      model_line1: "Inverter",
      model_line2: "Direct Drive",
      show_panel: true,
      show_energy: true,
      confirm_stop: true,
      start_option: "start",
      pause_option: "stop",
      stop_option: "power_off",
      programs: DEFAULT_PROGRAMS,
      program_map: {},
      ...config,
    };
    this._sig = null;
    if (this._hass) this._render();
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  getCardSize() {
    return this._config?.show_panel === false ? 5 : 7;
  }

  getGridOptions() {
    return { columns: "full", min_columns: 6, rows: "auto" };
  }

  connectedCallback() {
    this._timer = setInterval(() => this._render(), 15000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
  }

  /* ----------------------------- encje ----------------------------- */

  _eid(key) {
    const c = this._config;
    if (c.entities && c.entities[key]) return c.entities[key];
    const def = ENTITY_DEFAULTS[key];
    if (!def || !c.prefix) return null;
    return `${def[0]}.${c.prefix}_${def[1]}`;
  }

  _st(key) {
    const id = this._eid(key);
    return id ? this._hass.states[id] : undefined;
  }

  /* --------------------------- obliczenia -------------------------- */

  _remainingMin() {
    const st = this._st("remaining_time");
    if (!ok(st)) return null;
    const num = Number(st.state);
    if (!isNaN(num)) {
      const u = (st.attributes.unit_of_measurement || "min").toLowerCase();
      return u === "h" ? num * 60 : u === "s" ? num / 60 : num;
    }
    const t = Date.parse(st.state);
    if (isNaN(t)) return null;
    return Math.max(0, (t - Date.now()) / 60000);
  }

  _totalMin() {
    const st = this._st("total_time");
    if (!ok(st)) return null;
    const num = Number(st.state);
    if (isNaN(num)) return null;
    const u = (st.attributes.unit_of_measurement || "min").toLowerCase();
    return u === "h" ? num * 60 : u === "s" ? num / 60 : num;
  }

  _programName() {
    const st = this._st("program");
    if (!ok(st)) return null;
    const map = this._config.program_map || {};
    return map[st.state] ?? map[String(st.state).toLowerCase()] ?? st.state;
  }

  _stateOf(key, unitFallback = "") {
    const st = this._st(key);
    if (!ok(st)) return null;
    const u = st.attributes.unit_of_measurement ?? unitFallback;
    return `${esc(st.state)}${u ? " " + esc(u) : ""}`;
  }

  /* ---------------------------- akcje ------------------------------ */

  _moreInfo(key) {
    const entityId = this._eid(key);
    if (!entityId) return;
    const ev = new Event("hass-more-info", { bubbles: true, composed: true });
    ev.detail = { entityId };
    this.dispatchEvent(ev);
  }

  _op(option) {
    const id = this._eid("operation");
    if (!id) return;
    this._hass.callService("select", "select_option", { entity_id: id, option });
  }

  // klik w nazwę programu na panelu -> ustawia input_select/select z programem
  _setProgram(idx) {
    const id = this._eid("program");
    const name = (this._config.programs || DEFAULT_PROGRAMS)[idx];
    const st = id && this._hass.states[id];
    if (!st || !name) return;
    const opts = st.attributes.options || [];
    const map = this._config.program_map || {};
    // szukamy opcji: dokładnie, po program_map (odwrotnie) albo po znormalizowanej nazwie
    const option =
      opts.find((o) => o === name) ||
      opts.find((o) => map[o] === name) ||
      opts.find((o) => normalize(o) === normalize(name)) ||
      opts.find((o) => normalize(map[o]) === normalize(name));
    if (!option) return;
    this._hass.callService(id.split(".")[0], "select_option", { entity_id: id, option });
  }

  _action(a) {
    const c = this._config;
    const status = this._st("status")?.state;
    switch (a) {
      case "power": {
        const id = this._eid("power");
        if (id) this._hass.callService("switch", "toggle", { entity_id: id });
        break;
      }
      case "playpause":
        if (ACTIVE.includes(status)) this._op(c.pause_option);
        else this._op(c.start_option);
        break;
      case "stop":
        if (!IN_CYCLE.includes(status)) return;
        if (c.confirm_stop && !window.confirm("Przerwać bieżące pranie?")) return;
        this._op(c.stop_option);
        break;
      default:
        if (a.startsWith("info:")) this._moreInfo(a.slice(5));
        if (a.startsWith("prog:")) this._setProgram(Number(a.slice(5)));
    }
  }

  /* ---------------------------- render ----------------------------- */

  _render() {
    if (!this._config || !this._hass) return;
    const keys = Object.keys(ENTITY_DEFAULTS);
    const sig =
      keys.map((k) => {
        const s = this._st(k);
        return s ? s.state + "|" + s.last_updated : "-";
      }).join(";") + "@" + Math.floor(Date.now() / 15000);
    if (sig === this._sig) return;
    this._sig = sig;

    if (!this.shadowRoot) {
      this.attachShadow({ mode: "open" });
      this.shadowRoot.addEventListener("click", (e) => {
        const el = e.composedPath().find((n) => n.dataset && n.dataset.action);
        if (el && !el.hasAttribute("disabled")) this._action(el.dataset.action);
      });
    }

    const c = this._config;
    const statusSt = this._st("status");
    const status = statusSt?.state ?? "unknown";
    const avail = statusSt && statusSt.state !== "unavailable";
    const powerOn = this._st("power")?.state === "on";
    const active = ACTIVE.includes(status);
    const inCycle = IN_CYCLE.includes(status);
    const paused = status === "pause";
    const stage = STAGE_OF[status];

    const remaining = inCycle || status === "end" ? this._remainingMin() : null;
    const total = this._totalMin();
    const remStr = status === "end" ? "0:00" : fmtHM(remaining);
    const totStr = inCycle ? fmtHM(total) : null;
    let pct = 0;
    if (status === "end") pct = 100;
    else if (inCycle && total > 0 && remaining != null) pct = Math.min(100, Math.max(0, Math.round(((total - remaining) / total) * 100)));

    const program = this._programName();
    const temp = this._stateOf("temperature", "°C");
    const spin = this._stateOf("spin", "obr/min");

    const delayH = Number(this._st("delayed_end")?.state);
    const delayTs = this._st("delayed_end_time");
    let delayStr = "Wyłączony";
    if (delayH > 0) {
      delayStr = `${delayH} h`;
      if (ok(delayTs) && !isNaN(Date.parse(delayTs.state))) {
        const d = new Date(delayTs.state);
        delayStr += ` · ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
      }
    }

    const remoteOn = this._st("remote_start")?.state === "on";

    // status + podpis
    let statusText = STATUS_PL[status] ?? status;
    let dotClass = "idle";
    let sub = "Brak aktywnego prania";
    if (active) { dotClass = "run"; sub = program || STATUS_PL[status]; if (status === "running") statusText = "W trakcie prania"; }
    if (paused) { dotClass = "pause"; sub = program || "Cykl wstrzymany"; }
    if (status === "reserved") { dotClass = "pause"; sub = program || "Oczekuje na start"; }
    if (status === "end") { dotClass = "end"; sub = program || "Można wyjmować pranie"; }
    if (status === "error") {
      dotClass = "err";
      const ev = this._st("error");
      sub = ev?.attributes?.event_type ? ERROR_PL[ev.attributes.event_type] || ev.attributes.event_type : "Sprawdź pralkę";
    }
    if (!avail) { dotClass = "err"; statusText = "Niedostępna"; sub = "Brak połączenia z LG ThinQ"; }
    if (active && program) sub = program;
    else if (active) sub = "";

    const drumMode = active ? "active" : paused || status === "rinse_hold" ? "paused" : "idle";

    // program na pokrętle
    const progs = c.programs || DEFAULT_PROGRAMS;
    const half = Math.ceil(progs.length / 2);
    const left = progs.slice(0, half);
    const right = progs.slice(half);
    const pIdx = program ? progs.findIndex((p) => normalize(p) === normalize(program)) : -1;
    let dialAngle = 0;
    // lewa kolumna: od -30° (góra) do -150° (dół), prawa: od 30° do 150°
    if (pIdx >= 0 && pIdx < half) dialAngle = -(30 + pIdx * (120 / Math.max(1, half - 1)));
    else if (pIdx >= half) dialAngle = 30 + (pIdx - half) * (120 / Math.max(1, right.length - 1));

    const progEid = this._eid("program");
    const progClick = !!progEid && /^(input_select|select)\./.test(progEid);
    const progList = (arr, off) =>
      arr
        .map(
          (p, i) =>
            `<div class="prog ${off + i === pIdx ? "sel" : ""}" ${progClick ? `data-action="prog:${off + i}"` : ""}><span class="tick"></span><span>${esc(p)}</span></div>`
        )
        .join("");

    const icon = (name) => `<ha-icon icon="${name}"></ha-icon>`;
    const tile = (k, ic, label, value, opts = {}) => `
      <div class="tile ${opts.dim ? "dim" : ""} ${opts.cls || ""}" data-action="info:${k}" role="button" tabindex="0">
        <div class="ic ${opts.icCls || ""}">${icon(ic)}</div>
        <div class="tx"><div class="lb">${label}</div><div class="val ${opts.valCls || ""}">${value ?? "-"}</div></div>
        <div class="chev">${icon("mdi:chevron-right")}</div>
      </div>`;

    const disp = remStr ?? "-:--";
    const panel = !c.show_panel ? "" : `
      <div class="panel">
        <div class="brand">
          <div class="logo">${esc(c.brand)}</div>
          <div class="model"><span>${esc(c.model_line1)}</span><span>${esc(c.model_line2)}</span></div>
        </div>
        <button class="rbtn pwr ${powerOn ? "on" : ""}" data-action="power" title="Zasilanie">${icon("mdi:power")}</button>
        <div class="progs l ${progClick ? "click" : ""}">${progList(left, 0)}</div>
        <div class="dial-wrap"><div class="dial" style="transform:rotate(${this._prevDial ?? dialAngle}deg)"><span class="mark ${pIdx >= 0 || powerOn || inCycle ? "lit" : ""}"></span></div></div>
        <div class="progs r ${progClick ? "click" : ""}">${progList(right, half)}</div>
        <button class="rbtn play ${active ? "on" : ""}" data-action="playpause" title="Start / Pauza">${icon("mdi:play-pause")}</button>
        <div class="display">
          <div class="dmain">
            <div class="dicons">
              <span class="${avail ? "lit" : ""}">${icon("mdi:wifi")}</span>
              <span class="${inCycle ? "lit" : ""}">${icon("mdi:lock-outline")}</span>
              <span>${icon("mdi:tshirt-crew-outline")}</span>
              <span>${icon("mdi:heat-wave")}</span>
            </div>
            <div class="dtime ${remStr ? "lit" : ""}">${esc(disp)}</div>
            <div class="dstages">
              ${STAGES.map((s, i) => `<div class="stg ${stage === i ? "cur" : ""} ${stage > i ? "done" : ""}">${inCycle || status === "end" ? icon(STAGE_ICONS[i]) : "<i></i>"}<span>${s}</span></div>`).join("")}
            </div>
          </div>
          <div class="dside">
            <div>${icon("mdi:thermometer")}<span><small>Temp.</small>${temp ?? "- °C"}</span></div>
            <div>${icon("mdi:fan")}<span><small>Wirowanie</small>${spin ?? "- obr/min"}</span></div>
            <div>${icon("mdi:clock-outline")}<span><small>Opóźnienie</small>${delayH > 0 ? delayH + " h" : "-"}</span></div>
          </div>
        </div>
        <div class="thinq">ThinQ</div>
      </div>`;

    const energy = !c.show_energy ? "" : `
      <div class="energy">
        <div class="en" data-action="info:energy_today">${icon("mdi:lightning-bolt-outline")}<div><small>Dzisiaj</small><b>${fmtEnergy(this._st("energy_today"))}</b></div></div>
        <div class="en" data-action="info:energy_yesterday">${icon("mdi:chart-bar")}<div><small>Wczoraj</small><b>${fmtEnergy(this._st("energy_yesterday"))}</b></div></div>
        <div class="en" data-action="info:energy_this_month">${icon("mdi:calendar-month-outline")}<div><small>Ten miesiąc</small><b>${fmtEnergy(this._st("energy_this_month"))}</b></div></div>
        <div class="en" data-action="info:energy_last_month">${icon("mdi:calendar-blank-outline")}<div><small>Poprzedni miesiąc</small><b>${fmtEnergy(this._st("energy_last_month"))}</b></div></div>
        <div class="en" data-action="info:cycles">${icon("mdi:history")}<div><small>Liczba cykli</small><b>${ok(this._st("cycles")) ? esc(this._st("cycles").state) : "–"}</b></div></div>
      </div>`;

    const useSvg = c.drum_style === "svg";
    const busy = active || paused || status === "rinse_hold";
    const drumImg = busy ? c.image_active || (useSvg ? null : DRUM_PHOTO_ACTIVE) : c.image_idle || (useSvg ? null : DRUM_PHOTO_IDLE);
    const builtIn = drumImg === DRUM_PHOTO_ACTIVE || drumImg === DRUM_PHOTO_IDLE;
    const drumHtml = !drumImg
      ? drumSvg(drumMode)
      : builtIn
      ? `<div class="photo ${busy ? "busy" : ""}"><img src="${drumImg}" alt="">${busy ? `<img class="inner" src="${drumImg}" alt="">` : ""}</div>`
      : `<img src="${esc(drumImg)}" alt="">`;

    this.shadowRoot.innerHTML = `
      <style>${STYLES}</style>
      <ha-card>
        <div class="wrap">
          ${panel}
          <div class="body">
            <div class="drum ${drumMode}">${drumHtml}</div>
            <div class="info">
              <div class="sub1">${esc(c.subtitle)}</div>
              <div class="name">${esc(c.name)}</div>
              <div class="status"><span class="dot ${dotClass}"></span><span class="st ${dotClass}">${esc(statusText)}</span></div>
              <div class="sub2 ${active || paused ? "ind" : ""}">${esc(sub)}</div>
              ${inCycle || status === "end" ? `<div class="remlbl">Pozostały czas</div>` : ""}
              <div class="rem ${remStr ? "" : "none"}">${esc(remStr ?? "- : - -")}<span class="pct">${pct}%</span></div>
              <div class="bar"><div style="width:${pct}%"></div></div>
            </div>
            <div class="tiles">
              ${tile("program", "mdi:leaf", "Program", esc(program ?? "-"), { icCls: "green" + (program ? "" : " dimic"), dim: !program })}
              ${tile("temperature", "mdi:thermometer", "Temperatura", temp ?? "-", { dim: !temp })}
              ${tile("spin", "mdi:fan", "Wirowanie", spin ?? "-", { dim: !spin })}
              ${tile("status", "mdi:tshirt-crew-outline", "Aktualny etap", stage != null && inCycle ? STAGES[stage] : status === "end" ? "Koniec" : "-", { dim: !(inCycle || status === "end") })}
              ${tile("total_time", "mdi:clock-outline", "Całkowity czas", totStr ?? "-", { dim: !totStr })}
              ${tile("delayed_end", "mdi:timer-outline", "Opóźniony koniec", delayStr)}
              <div class="actions">
                <div class="act" data-action="power" role="button" tabindex="0">
                  <div class="ic">${icon("mdi:power")}</div>
                  <div class="tx"><div class="lb">Zasilanie</div><div class="val ${powerOn ? "on" : "off"}">${powerOn ? "Włączona" : "Wyłączona"}</div></div>
                </div>
                <div class="act big" data-action="playpause" role="button" tabindex="0" ${!avail ? "disabled" : ""}>
                  <div class="ic plain">${icon(active ? "mdi:play-pause" : "mdi:play")}</div>
                  <div class="tx"><div class="val">${active ? "Pauza" : paused ? "Wznów" : "Start"}</div></div>
                </div>
                <div class="act big" data-action="stop" role="button" tabindex="0" ${inCycle ? "" : "disabled"}>
                  <div class="ic plain">${icon("mdi:stop")}</div>
                  <div class="tx"><div class="val">Stop</div></div>
                </div>
                <div class="act ${remoteOn ? "" : "off"}" data-action="info:remote_start" role="button" tabindex="0">
                  <div class="ic">${icon("mdi:remote")}</div>
                  <div class="tx"><div class="lb">Zdalny start</div><div class="val ${remoteOn ? "on" : ""}">${remoteOn ? "Dostępny" : "Niedostępny"}</div></div>
                </div>
              </div>
            </div>
            ${energy}
          </div>
        </div>
      </ha-card>`;

    // płynny obrót gałki ze starej pozycji do nowej
    const dial = this.shadowRoot.querySelector(".dial");
    if (dial && this._prevDial !== dialAngle) {
      requestAnimationFrame(() => requestAnimationFrame(() => (dial.style.transform = `rotate(${dialAngle}deg)`)));
    }
    this._prevDial = dialAngle;
  }
}

/* ------------------------------------------------------------------ */
/*  Style                                                              */
/* ------------------------------------------------------------------ */

const STYLES = `
:host { display:block; --lgw-bg:#0f1720; --lgw-tile:#172230; --lgw-tile2:#1b2838; --lgw-line:#223044;
  --lgw-txt:#e9eef4; --lgw-mut:#8d9aab; --lgw-blue:#3b8cff; --lgw-green:#3ecf6a; --lgw-red:#ff4d4f; --lgw-orange:#ffad33; }
ha-card { background:#16191d; border-radius:22px; overflow:hidden; color:var(--lgw-txt);
  border:1px solid #2a2e33; box-shadow:0 8px 30px rgba(0,0,0,.35); container-type:inline-size; }
.wrap { padding:6px; }
ha-icon { --mdc-icon-size:22px; display:inline-flex; }

/* ---------- panel ---------- */
.panel { position:relative; display:grid; align-items:center; gap:14px;
  grid-template-columns: 1.3fr 64px auto 160px auto 70px minmax(300px,2.2fr) 50px;
  padding:16px 20px; border-radius:18px 18px 6px 6px;
  background: linear-gradient(180deg,#4a4f55 0%,#2a2e33 6%,#1f2226 50%,#2b2f34 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18), inset 0 -2px 0 rgba(0,0,0,.6); }
.panel::before { content:""; position:absolute; inset:0; border-radius:inherit; pointer-events:none;
  background: repeating-linear-gradient(90deg, rgba(255,255,255,.025) 0 1px, transparent 1px 3px); }
.brand { display:flex; flex-direction:column; gap:22px; }
.logo { font: 600 34px/1 system-ui, sans-serif; letter-spacing:1px; color:#d6dade; text-shadow:0 1px 0 #000; }
.model { display:flex; flex-direction:column; color:#c3c8ce; }
.model span:first-child { font-size:14px; }
.model span:last-child { font-size:20px; letter-spacing:.2px; }
.rbtn { all:unset; cursor:pointer; width:52px; height:52px; border-radius:50%; display:flex; align-items:center; justify-content:center;
  background: radial-gradient(circle at 40% 35%, #3a3f45, #16191c); border:2px solid #4b5056; color:#cfd4d9;
  box-shadow: 0 2px 6px rgba(0,0,0,.6); }
.rbtn ha-icon { --mdc-icon-size:28px; }
.rbtn.on { color:#5fb0ff; border-color:#7fc1ff; box-shadow:0 0 14px rgba(80,160,255,.55), 0 2px 6px rgba(0,0,0,.6); }
.rbtn.play { width:56px; height:56px; border-color:#cfd4d9; color:#fff; }
.progs { display:flex; flex-direction:column; gap:3px; font-size:14px; color:#cfd4d9; white-space:nowrap; }
.progs .prog { display:flex; align-items:center; gap:10px; }
.progs .tick { width:40px; height:1px; background:#5c6268; flex:none; transition:all .3s; }
.progs.l .tick { order:2; }
.progs.click .prog { cursor:pointer; }
.progs.click .prog:hover { color:#fff; }
.progs .sel { color:#fff; font-weight:600; text-shadow:0 0 8px rgba(59,156,255,.6); }
.progs .sel .tick { background:#3b9cff; height:3px; border-radius:2px; box-shadow:0 0 6px #3b9cff; }
.dial-wrap { width:150px; height:150px; border-radius:50%; justify-self:center; padding:6px;
  background: radial-gradient(circle,#0a0b0d 60%,#2c3035 100%); box-shadow:0 6px 18px rgba(0,0,0,.7); }
.dial { width:100%; height:100%; border-radius:50%; position:relative; transition:transform .6s ease;
  background: conic-gradient(from 0deg,#8e959c,#e3e7ea,#6d737a,#cfd4d8,#5e646b,#e3e7ea,#8e959c,#d0d5d9,#8e959c);
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.25), inset 0 -6px 14px rgba(0,0,0,.45); }
.dial::after { content:""; position:absolute; inset:18%; border-radius:50%;
  background: repeating-conic-gradient(rgba(255,255,255,.06) 0 2deg, rgba(0,0,0,.05) 2deg 4deg); }
.dial .mark { position:absolute; left:50%; top:9px; width:4px; height:26px; margin-left:-2px; border-radius:2px; background:#e8ecef; z-index:1; }
.dial .mark.lit { background:#4aa6ff; box-shadow:0 0 8px #4aa6ff; }
.display { display:grid; grid-template-columns:1fr auto; gap:8px; background:#06080b; border-radius:12px; padding:12px 14px;
  border:1px solid #23272c; box-shadow: inset 0 0 18px rgba(0,0,0,.9); min-height:120px; }
.dmain { display:flex; flex-direction:column; align-items:center; justify-content:space-between; }
.dicons { display:flex; gap:22px; color:#59616a; }
.dicons .lit { color:#e7f2ff; }
.dicons ha-icon { --mdc-icon-size:20px; }
.dtime { font: 300 52px/1 "Segoe UI", system-ui, sans-serif; letter-spacing:4px; color:#3a4048; font-style:italic; margin:4px 0; }
.dtime.lit { color:#bfe0ff; text-shadow:0 0 10px #3b9cff, 0 0 22px rgba(59,156,255,.6); }
.dstages { display:flex; gap:10px; }
.stg { display:flex; flex-direction:column; align-items:center; font-size:12px; color:#5d6670; gap:2px; }
.stg ha-icon { --mdc-icon-size:18px; }
.stg i { width:14px; height:2px; background:#3a4048; margin:8px 0; }
.stg.done { color:#8fa0b4; }
.stg.cur { color:#7cc0ff; }
.stg.cur span { text-decoration:underline; text-underline-offset:3px; color:#bfe0ff; }
.dside { border-left:1px solid #2a2f35; padding-left:12px; display:flex; flex-direction:column; justify-content:space-around; gap:6px; color:#9aa4ae; font-size:12px; }
.dside > div { display:flex; align-items:center; gap:8px; }
.dside ha-icon { --mdc-icon-size:20px; color:#cfd4d9; }
.dside span { display:flex; flex-direction:column; color:#cfd4d9; }
.dside small { color:#9aa4ae; font-size:11px; }
.thinq { align-self:start; color:#cfd4d9; font-size:17px; }

/* ---------- body ---------- */
.body { margin-top:6px; display:grid; gap:10px; padding:10px; border-radius:6px 6px 18px 18px;
  background: linear-gradient(180deg,#121b26,#0f1720);
  grid-template-columns: 300px minmax(220px,0.95fr) 2.6fr;
  grid-template-areas: "drum info tiles" "drum energy energy"; }
.drum { grid-area:drum; border-radius:14px; overflow:hidden; background:#0c1015; min-height:260px; min-width:0; }
.drum svg, .drum > img { width:100%; height:100%; display:block; object-fit:cover; }
.drum { display:flex; align-items:center; justify-content:center; background:#0b0d10; }
.drum .photo { position:relative; width:100%; aspect-ratio:304/294; }
.drum .photo img { position:absolute; inset:0; width:100%; height:100%; display:block; }
.drum .photo .inner { clip-path: circle(36.5% at 51.5% 50.5%); transform-origin:51.5% 50.5%; }
.drum.active .photo .inner { animation: lgw-spin 6s linear infinite; }
.drum .spin { transform-origin:160px 160px; animation: lgw-spin 3s linear infinite; }
.drum.active .lgw-water { animation: lgw-slosh 2.2s ease-in-out infinite alternate; }
.drum.active .lgw-bubbles { animation: lgw-bub 3s linear infinite; }
@keyframes lgw-spin { to { transform: rotate(360deg); } }
@keyframes lgw-slosh { from { transform: translateX(-10px) rotate(-3deg);} to { transform: translateX(10px) rotate(3deg);} }
@keyframes lgw-bub { from { transform: translateY(0); opacity:1;} to { transform: translateY(-40px); opacity:.2;} }

.info { grid-area:info; padding:12px 8px 0 12px; display:flex; flex-direction:column; min-width:0; }
.sub1 { color:var(--lgw-mut); font-size:15px; }
.name { font-size:25px; font-weight:600; margin:2px 0 12px; }
.status { display:flex; align-items:center; gap:10px; font-size:18px; }
.dot { width:16px; height:16px; border-radius:50%; background:#c7ccd2; flex:none; }
.dot.run { background:var(--lgw-blue); box-shadow:0 0 8px var(--lgw-blue); }
.dot.pause { background:var(--lgw-orange); }
.dot.end { background:var(--lgw-green); }
.dot.err { background:var(--lgw-red); }
.st.run { color:#4c9dff; } .st.pause { color:var(--lgw-orange);} .st.end { color:var(--lgw-green);} .st.err { color:var(--lgw-red);} .st.idle { color:#e3e7eb; }
.sub2 { color:var(--lgw-mut); font-size:16px; margin-top:6px; min-height:20px; }
.sub2.ind { padding-left:28px; color:#b9c3cf; }
.remlbl { color:var(--lgw-mut); font-size:16px; margin-top:16px; }
.rem { display:flex; align-items:baseline; justify-content:space-between; font-size:48px; font-weight:600; letter-spacing:1px; margin-top:2px; }
.rem.none { margin-top:22px; font-size:34px; }
.rem .pct { font-size:21px; font-weight:400; }
.bar { height:14px; border-radius:8px; background:#243246; margin-top:8px; overflow:hidden; }
.bar div { height:100%; border-radius:8px; background:linear-gradient(90deg,#2f7ff0,#4aa3ff); transition:width .6s; }

.tiles { grid-area:tiles; display:grid; grid-template-columns:repeat(3,1fr); gap:10px; align-content:start; }
.tile, .act { display:flex; align-items:center; gap:14px; padding:12px 16px; border-radius:12px; cursor:pointer;
  background:var(--lgw-tile); border:1px solid rgba(255,255,255,.03); min-height:56px; min-width:0; transition:background .15s; }
.tile:hover, .act:hover { background:var(--lgw-tile2); }
.ic { width:46px; height:46px; border-radius:50%; display:flex; align-items:center; justify-content:center; flex:none;
  background:#1f2c3c; color:#e8edf2; }
.ic.plain { background:transparent; width:36px; }
.ic.plain ha-icon { --mdc-icon-size:32px; }
.ic.green { color:var(--lgw-green); }
.ic.dimic { color:#8fa0b0; }
.tx { flex:1; min-width:0; }
.lb { color:#aab5c2; font-size:13px; }
.val { font-size:16px; font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.tile.dim .val { color:#aab5c2; font-weight:400; }
.chev { color:#c7ced6; }
.val.on { color:var(--lgw-green); font-weight:500; } .val.off { color:var(--lgw-red); font-weight:500; }
.actions { grid-column:1/-1; display:grid; grid-template-columns:1.2fr 1fr 1fr 1.2fr; gap:10px; }
.act.big .val { font-weight:500; }
.act[disabled] { opacity:.45; cursor:default; }
.act.off .val, .act.off .lb, .act.off .ic { color:#6f7c8a; }
.energy { grid-area:energy; display:grid; grid-template-columns:repeat(5,1fr); border-top:1px solid var(--lgw-line); padding-top:10px; }
.en { display:flex; align-items:center; gap:14px; padding:4px 16px; border-left:1px solid var(--lgw-line); cursor:pointer; min-width:0; }
.en:first-child { border-left:none; }
.en ha-icon { color:#c7ced6; --mdc-icon-size:26px; }
.en div { display:flex; flex-direction:column; min-width:0; }
.en small { color:var(--lgw-mut); font-size:13px; }
.en b { font-weight:500; font-size:16px; white-space:nowrap; }

/* ---------- responsywność ---------- */
@container (max-width: 1250px) {
  .panel { grid-template-columns: auto 56px 150px 64px minmax(260px,1fr) auto; }
  .progs { display:none; }
  .dial-wrap { width:120px; height:120px; }
  .body { grid-template-columns: 240px minmax(200px,1fr) 2fr; }
}
@container (max-width: 980px) {
  .panel { grid-template-columns: auto 56px 1fr 64px; }
  .dial-wrap { width:110px; height:110px; }
  .thinq { display:none; }
  .display { grid-column: 1 / -1; }
  .body { grid-template-columns: 200px 1fr; grid-template-areas: "drum info" "tiles tiles" "energy energy"; }
  .tiles { grid-template-columns: repeat(3,1fr); }
  .energy { grid-template-columns: repeat(5,1fr); }
}
@container (max-width: 680px) {
  .dial-wrap { display:none; }
  .body { grid-template-columns: 140px 1fr; padding:8px; }
  .tiles { grid-template-columns: repeat(2,1fr); }
  .actions { grid-template-columns: repeat(2,1fr); }
  .energy { grid-template-columns: repeat(3,1fr); row-gap:10px; }
  .en { padding:4px 8px; border-left:none; gap:8px; }
  .rem { font-size:36px; } .name { font-size:21px; }
  .chev { display:none; }
  .tile, .act { padding:10px; gap:10px; }
  .ic { width:38px; height:38px; }
  .dtime { font-size:40px; }
  .dside { display:none; }
  .display { grid-template-columns:1fr; }
  .brand { gap:6px; } .logo { font-size:26px; } .model span:last-child { font-size:15px; }
}
@container (max-width: 420px) {
  .body { grid-template-columns: 1fr; grid-template-areas: "drum" "info" "tiles" "energy"; }
  .drum { max-width:200px; justify-self:center; width:100%; }
  .energy { grid-template-columns: repeat(2,1fr); }
}
`;

/* ------------------------------------------------------------------ */
/*  Edytor wizualny                                                    */
