const EDITOR_SCHEMA = [
  { name: "name", label: "Nazwa", selector: { text: {} } },
  { name: "prefix", label: "Prefix encji (np. frania)", selector: { text: {} } },
  {
    type: "grid", name: "", schema: [
      { name: "show_panel", label: "Pokaż panel pralki", selector: { boolean: {} } },
      { name: "show_energy", label: "Pokaż energię", selector: { boolean: {} } },
      { name: "confirm_stop", label: "Potwierdzaj Stop", selector: { boolean: {} } },
    ],
  },
  {
    type: "expandable", name: "entities", title: "Encje opcjonalne / nadpisania", schema: [
      { name: "program", label: "Program (sensor)", selector: { entity: {} } },
      { name: "temperature", label: "Temperatura", selector: { entity: {} } },
      { name: "spin", label: "Wirowanie", selector: { entity: {} } },
    ],
  },
  { name: "image_active", label: "Obraz bębna – pranie (URL, opcjonalnie)", selector: { text: {} } },
  { name: "image_idle", label: "Obraz bębna – bezczynność (URL, opcjonalnie)", selector: { text: {} } },
];

class LgThinqWasherCardEditor extends HTMLElement {
  setConfig(config) {
    this._config = config;
    this._render();
  }
  set hass(hass) {
    this._hass = hass;
    this._render();
  }
  _render() {
    if (!this._hass || !this._config) return;
    if (!this._form) {
      this._form = document.createElement("ha-form");
      this._form.computeLabel = (s) => s.label ?? s.title ?? s.name;
      this._form.addEventListener("value-changed", (ev) => {
        const config = { ...ev.detail.value };
        if (config.entities) {
          Object.keys(config.entities).forEach((k) => !config.entities[k] && delete config.entities[k]);
          if (!Object.keys(config.entities).length) delete config.entities;
        }
        const e = new Event("config-changed", { bubbles: true, composed: true });
        e.detail = { config };
        this.dispatchEvent(e);
      });
      this.appendChild(this._form);
    }
    this._form.hass = this._hass;
    this._form.schema = EDITOR_SCHEMA;
    this._form.data = { show_panel: true, show_energy: true, confirm_stop: true, ...this._config };
  }
}

if (!customElements.get("lg-thinq-washer-panel-card")) customElements.define("lg-thinq-washer-panel-card", LgThinqWasherCard);
if (!customElements.get("lg-thinq-washer-panel-card-editor")) customElements.define("lg-thinq-washer-panel-card-editor", LgThinqWasherCardEditor);

window.customCards = window.customCards || [];
if (!window.customCards.some((c) => c.type === "lg-thinq-washer-panel-card")) {
  window.customCards.push({
    type: "lg-thinq-washer-panel-card",
    name: "LG ThinQ Washer Panel Card",
    description: "Kafelek pralki LG ThinQ w stylu panelu urządzenia (status, czas, sterowanie, energia).",
    preview: true,
    documentationURL: "https://github.com/",
  });
}

console.info(`%c LG-THINQ-WASHER-PANEL-CARD %c v${CARD_VERSION} `, "background:#3b8cff;color:#fff;font-weight:700", "background:#16191d;color:#fff");
